import{_ as e,o as i,c as l,ae as o}from"./chunks/framework.FQ5RHm_v.js";const m=JSON.parse('{"title":"wvke-sdk | ¡Personalización Perfecta!","titleTemplate":false,"description":"","frontmatter":{"title":"wvke-sdk | ¡Personalización Perfecta!","titleTemplate":false},"headers":[],"relativePath":"es/index.md","filePath":"es/index.md"}'),s={name:"es/index.md"};function t(r,a,n,d,c,p){return i(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="wvke-sdk" tabindex="-1">wvke-sdk <a class="header-anchor" href="#wvke-sdk" aria-label="Permalink to &quot;wvke-sdk&quot;">​</a></h1><p>wvke-sdk es un SDK de JavaScript para comunicarse con periféricos gaming, incluidos teclados y ratones.</p><p>Construido sobre la moderna tecnología WebHID, permite la personalización profunda y el control inteligente de teclados, ratones y otros periféricos. Acelera la entrega de productos periféricos gaming y abre nuevas posibilidades en el ecosistema gaming. El proyecto es desarrollado y mantenido por el GDE Game Driver Engine Team.</p><h2 id="tipos-de-sdk" tabindex="-1">Tipos de SDK <a class="header-anchor" href="#tipos-de-sdk" aria-label="Permalink to &quot;Tipos de SDK&quot;">​</a></h2><h3 id="⌨️-teclado-lineal" tabindex="-1">⌨️ Teclado lineal <a class="header-anchor" href="#⌨️-teclado-lineal" aria-label="Permalink to &quot;⌨️ Teclado lineal&quot;">​</a></h3><p>Construido para teclados mecánicos:</p><ul><li>Mapeo de teclas y cambio de capa</li><li>Control de iluminación RGB</li><li>Autorización WebHID, lista de dispositivos autorizados e inicialización</li><li>Interruptor de recorrido completo RT, ajuste de recorrido y zona segura</li><li>Grabación y reproducción de macros</li><li>Ajuste de tasa de sondeo (1KHz-8KHz)</li><li>Cambio de modo de sistema (Windows/Mac)</li></ul><h3 id="🖱️-sdk-de-raton" tabindex="-1">🖱️ SDK de ratón <a class="header-anchor" href="#🖱️-sdk-de-raton" aria-label="Permalink to &quot;🖱️ SDK de ratón&quot;">​</a></h3><p>Construido para ratones gaming:</p><ul><li>Ajuste DPI (400-16000 DPI)</li><li>Programación de botones y macros</li><li>Personalización de iluminación RGB</li><li>Ajuste de distancia de elevación</li><li>Optimización de sondeo</li></ul><h2 id="caracteristicas" tabindex="-1">Características <a class="header-anchor" href="#caracteristicas" aria-label="Permalink to &quot;Características&quot;">​</a></h2><ul><li>Soporte moderno de JavaScript/TypeScript</li><li>Comunicación hardware WebHID</li><li>APIs completas de control de iluminación</li><li>APIs de mapeo de teclas y macros</li><li>APIs de recorrido RT, teclas avanzadas e inicialización</li><li>APIs de DPI y mapeo de botones de ratón</li><li>Servicio de actualización personalizada general</li><li>Documentación API detallada</li></ul><h2 id="tutorial" tabindex="-1">Tutorial <a class="header-anchor" href="#tutorial" aria-label="Permalink to &quot;Tutorial&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wvke-sdk</span></span></code></pre></div><p>Consulte la <a href="/wvke.sdkdoc/docs/es/api/info.html">documentación API</a> para obtener más detalles.</p>',15)])])}const h=e(s,[["render",t]]);export{m as __pageData,h as default};
